func isJSONMediaType(mediaType string) bool {
	lowered := strings.ToLower(mediaType)
	return lowered == "application/json" ||
		(strings.HasPrefix(lowered, "application/") && strings.HasSuffix(lowered, "+json"))
}

func providerURL(baseURL, endpoint string) string {
	base := strings.TrimRight(baseURL, "/")
	if strings.HasSuffix(base, "/v1") {
		joined, _ := url.JoinPath(base, endpoint)
		return joined
	}
	joined, _ := url.JoinPath(base, "v1", endpoint)
	return joined
}

func (s *Server) applyProviderAuth(request *http.Request, item provider) error {
	if len(item.EncryptedAPIKey) == 0 {
		return nil
	}
	plaintext, err := s.cipher.Decrypt(item.EncryptedAPIKey, "provider:"+item.ID.String()+":api-key")
	if err != nil || strings.TrimSpace(string(plaintext)) == "" || strings.ContainsAny(string(plaintext), "\r\n\x00") {
		return errProviderCredentials
	}
	request.Header.Set("Authorization", "Bearer "+string(plaintext))
	return nil
}

func (s *Server) chatCompletions(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	if p.AuthMethod == "api_key" && !p.HasScope("ai:chat") {
		writeError(w, http.StatusForbidden, "scope_denied", "API 키에 ai:chat scope가 없습니다.")
		return
	}
	mediaType, _, contentTypeErr := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if contentTypeErr != nil || !strings.EqualFold(mediaType, "application/json") {
		writeError(w, http.StatusUnsupportedMediaType, "content_type_invalid", "채팅 요청은 application/json 형식이어야 합니다.")
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, 4<<20)
	var payload map[string]any
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(&payload); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "채팅 요청 본문이 올바르지 않습니다.")
		return
	}
	var trailing json.RawMessage
	if err := decoder.Decode(&trailing); err != io.EOF {
		writeError(w, http.StatusBadRequest, "invalid_json", "채팅 요청 본문이 올바르지 않습니다.")
		return
	}
	providerIDText, _ := payload["provider_id"].(string)
	delete(payload, "provider_id")
	if providerIDText == "" {
		providerIDText = s.stringSetting(r.Context(), "ai.default_provider_id", "")
	}
	providerID, err := uuid.Parse(providerIDText)
	if err != nil {
		writeError(w, http.StatusServiceUnavailable, "provider_not_configured", "기본 AI 공급자가 설정되지 않았습니다.")
		return
	}
	item, err := s.loadProvider(r.Context(), providerID)
	if err != nil || !item.Enabled {
		writeError(w, http.StatusServiceUnavailable, "provider_unavailable", "선택한 AI 공급자를 사용할 수 없습니다.")
		return
	}
	if _, ok := payload["model"]; !ok {
		payload["model"] = item.DefaultModel
	}
	model, modelOK := payload["model"].(string)
	model = strings.TrimSpace(model)
	if !modelOK || model == "" || utf8.RuneCountInString(model) > 240 {
		writeError(w, http.StatusBadRequest, "model_invalid", "사용할 모델 이름이 올바르지 않습니다.")
		return
	}
	allowedModels := uniqueStrings(append([]string{item.DefaultModel}, item.AvailableModels...))
	if !containsString(allowedModels, model) {
		writeError(w, http.StatusBadRequest, "model_not_allowed", "선택한 모델은 이 공급자에 허용되지 않았습니다.")
		return
	}
	payload["model"] = model
	stream, hasStream := payload["stream"].(bool)
	if _, supplied := payload["stream"]; supplied && !hasStream {
		writeError(w, http.StatusBadRequest, "stream_invalid", "stream 값은 true 또는 false여야 합니다.")
		return
	}
	if !hasStream {
		stream = item.StreamDefault && s.boolSetting(r.Context(), "ai.stream_default", true)
		payload["stream"] = stream
	}
	_, hasMaxTokens := payload["max_tokens"]
	_, hasCompletionTokens := payload["max_completion_tokens"]
	if hasMaxTokens && hasCompletionTokens {
		writeError(w, http.StatusBadRequest, "max_tokens_conflict", "max_tokens와 max_completion_tokens 중 하나만 지정해 주세요.")
		return
	}
	for _, field := range []string{"max_tokens", "max_completion_tokens"} {
		if raw, ok := payload[field]; ok {
			value, valid := numberAsInt(raw)
			if !valid || value < 1 || value > item.MaxOutputTokens || value > 262144 {
				writeError(w, http.StatusBadRequest, "max_tokens_invalid", fmt.Sprintf("%s는 1~%d 사이여야 합니다.", field, item.MaxOutputTokens))
				return
			}
		}
	}
	if !hasMaxTokens && !hasCompletionTokens {
		payload["max_tokens"] = item.MaxOutputTokens
	}
	if !s.chatRequests.acquire(p.ID, item.ID) {
		w.Header().Set("Retry-After", "1")
		writeError(w, http.StatusTooManyRequests, "ai_concurrency_limited", "동시 AI 요청이 많습니다. 잠시 후 다시 시도해 주세요.")
		return
	}
	defer s.chatRequests.release(p.ID, item.ID)
	body, _ := json.Marshal(payload)
	ctx, cancel := context.WithTimeout(r.Context(), time.Duration(item.TimeoutSeconds)*time.Second)
	defer cancel()
	responseController := http.NewResponseController(w)
	_ = responseController.SetWriteDeadline(time.Now().Add(time.Duration(item.TimeoutSeconds+5) * time.Second))
	defer func() { _ = responseController.SetWriteDeadline(time.Time{}) }()
	upstream, _ := http.NewRequestWithContext(ctx, http.MethodPost, providerURL(item.BaseURL, "chat/completions"), bytes.NewReader(body))
	upstream.Header.Set("Content-Type", "application/json")
	upstream.Header.Set("Accept", "text/event-stream, application/json")
	if err := s.applyProviderAuth(upstream, item); err != nil {
		s.audit(r, p, "ai.chat", "ai_provider", item.ID.String(), "failure", map[string]any{"model": payload["model"], "reason": "provider_credentials_unavailable"})
		writeError(w, http.StatusServiceUnavailable, "provider_credentials_unavailable", "AI 공급자 인증 정보를 복호화하지 못했습니다. 암호화 키와 공급자 설정을 확인해 주세요.")
		return
	}
	client := *s.client
	client.Timeout = time.Duration(item.TimeoutSeconds) * time.Second
	started := time.Now()
	response, err := client.Do(upstream)
	if err != nil {
		s.audit(r, p, "ai.chat", "ai_provider", item.ID.String(), "failure", map[string]any{"model": payload["model"], "reason": "upstream_unreachable"})
		writeError(w, http.StatusBadGateway, "ai_upstream_unavailable", "AI 공급자에 연결하지 못했습니다.")
		return
	}
	defer response.Body.Close()
	if response.StatusCode < 200 || response.StatusCode >= 300 {
		upstreamBody, _ := io.ReadAll(io.LimitReader(response.Body, 64<<10))
		s.logger.Warn("AI upstream rejected request", "status", response.StatusCode, "provider_id", item.ID, "body_bytes", len(upstreamBody))
		s.audit(r, p, "ai.chat", "ai_provider", item.ID.String(), "failure", map[string]any{"model": payload["model"], "reason": "upstream_rejected", "status": response.StatusCode})
		writeError(w, http.StatusBadGateway, "ai_upstream_rejected", fmt.Sprintf("AI 공급자가 HTTP %d로 응답했습니다.", response.StatusCode))
		return
	}
	contentType := response.Header.Get("Content-Type")
	if stream {
		mediaType, _, parseErr := mime.ParseMediaType(contentType)
		if parseErr != nil || !strings.EqualFold(mediaType, "text/event-stream") {
			_, _ = io.Copy(io.Discard, io.LimitReader(response.Body, 64<<10))
			s.audit(r, p, "ai.chat", "ai_provider", item.ID.String(), "failure", map[string]any{"model": payload["model"], "reason": "invalid_stream_content_type"})
			writeError(w, http.StatusBadGateway, "ai_stream_invalid", "AI 공급자가 스트리밍 형식으로 응답하지 않았습니다.")
			return
		}
		contentType = "text/event-stream; charset=utf-8"
		w.Header().Set("Cache-Control", "no-cache, no-transform")
		w.Header().Set("X-Accel-Buffering", "no")
	} else {
		// A non-streaming answer promises JSON just as firmly as a streamed one
		// promises events. Re-emitting whatever media type the provider chose would
		// let a misconfigured or compromised upstream label a body text/html on the
		// console origin, so anything that is not JSON is refused instead of relayed.
		if contentType != "" {
			mediaType, _, parseErr := mime.ParseMediaType(contentType)
			if parseErr != nil || !isJSONMediaType(mediaType) {
				_, _ = io.Copy(io.Discard, io.LimitReader(response.Body, 64<<10))
				s.audit(r, p, "ai.chat", "ai_provider", item.ID.String(), "failure", map[string]any{"model": payload["model"], "reason": "invalid_response_content_type"})
				writeError(w, http.StatusBadGateway, "ai_response_invalid", "AI 공급자가 JSON 형식으로 응답하지 않았습니다.")
				return
			}
		}
		contentType = "application/json; charset=utf-8"
	}
	w.Header().Set("Content-Type", contentType)
	w.WriteHeader(response.StatusCode)
	relay := relayChatBody(ctx, w, responseController, response.Body, stream)
	result := "failure"
	if relay.completed {
		result = "success"
	}
	details := map[string]any{"model": payload["model"], "stream": stream, "latencyMs": time.Since(started).Milliseconds(), "complete": relay.completed}
	if relay.reason != "" {
		details["reason"] = relay.reason
	}
	s.audit(r, p, "ai.chat", "ai_provider", item.ID.String(), result, details)
	if relay.completed {
		return
	}
	s.logger.Warn("AI chat response truncated", "reason", relay.reason, "provider_id", item.ID, "stream", stream)
	// The 200 and part of the answer are already on the wire, so the failure can
	// no longer be reported as a status code. Aborting the response makes the
	// caller fail the request instead of reading a half-written answer that
	// looks like one the model finished on its own.
	panic(http.ErrAbortHandler)
}

// chatRelay reports whether the whole provider response reached the caller and,
// when it did not, why the relay stopped early.
type chatRelay struct {
	completed bool
	reason    string
}

// chatStreamChunkWriteTimeout bounds how long a single streamed chunk may take
// to reach the caller, so a stalled client cannot hold an upstream slot open.
const chatStreamChunkWriteTimeout = 30 * time.Second

// relayChatBody copies the provider response to the caller and tells the caller
// apart from the provider when the copy stops early: an upstream that hangs up
// mid-answer, a provider timeout, an abandoned request and a client that stopped
// reading all leave the response truncated but mean different things in audit.
func relayChatBody(ctx context.Context, w io.Writer, controller *http.ResponseController, body io.Reader, stream bool) chatRelay {
	buffer := make([]byte, 32<<10)
	for {
		read, readErr := body.Read(buffer)
		if read > 0 {
			if stream {
				_ = controller.SetWriteDeadline(time.Now().Add(chatStreamChunkWriteTimeout))
			}
			if _, err := w.Write(buffer[:read]); err != nil {
				return chatRelay{reason: "client_write_failed"}
			}
			if stream {
				if err := controller.Flush(); err != nil {
					return chatRelay{reason: "client_flush_failed"}
				}
			}
		}
		if readErr != nil {
			switch {
			case errors.Is(readErr, io.EOF):
				return chatRelay{completed: true}
			case errors.Is(ctx.Err(), context.DeadlineExceeded):
				return chatRelay{reason: "upstream_timeout"}
			case errors.Is(ctx.Err(), context.Canceled):
				return chatRelay{reason: "request_cancelled"}
			default:
				return chatRelay{reason: "upstream_read_failed"}
			}
		}
	}
}

func (s *Server) models(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	if !p.HasPermission("ai.providers.read") && !p.HasPermission("ai.use") {
		writeError(w, http.StatusForbidden, "permission_denied", "AI 모델을 조회할 권한이 없습니다.")
		return
	}
	if p.AuthMethod == "api_key" && !p.HasScope("ai:models") {
		writeError(w, http.StatusForbidden, "scope_denied", "API 키에 ai:models scope가 없습니다.")
		return
	}
	rows, err := s.db.Pool.Query(r.Context(), `SELECT id,name,default_model,available_models,created_at FROM ai_admin.ai_provider WHERE enabled=true ORDER BY name`)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "models_unavailable", "AI 모델 목록을 불러오지 못했습니다.")
		return
	}
	defer rows.Close()
	models := make([]map[string]any, 0)
	seen := map[string]bool{}
	for rows.Next() {
		var providerID uuid.UUID
		var providerName, defaultModel string
		var availableRaw []byte
		var created time.Time
		if err := rows.Scan(&providerID, &providerName, &defaultModel, &availableRaw, &created); err != nil {
			writeError(w, http.StatusInternalServerError, "models_unavailable", "AI 모델 목록을 불러오지 못했습니다.")
			return
		}
		var available []string
		_ = json.Unmarshal(availableRaw, &available)
		available = append([]string{defaultModel}, available...)
		for _, model := range uniqueStrings(available) {
			if model == "" || seen[providerID.String()+":"+model] {
				continue
			}
			seen[providerID.String()+":"+model] = true
			models = append(models, map[string]any{"id": model, "object": "model", "created": created.Unix(), "owned_by": providerName, "provider_id": providerID})
		}
	}
	if rows.Err() != nil {
		writeError(w, http.StatusInternalServerError, "models_unavailable", "AI 모델 목록을 불러오지 못했습니다.")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"object": "list", "data": models})
}

func (s *Server) aiCatalog(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	if !p.HasPermission("ai.providers.read") && !p.HasPermission("ai.use") {
		writeError(w, http.StatusForbidden, "permission_denied", "AI 모델을 사용할 권한이 없습니다.")
		return
	}
	if p.AuthMethod == "api_key" && !p.HasScope("ai:models") {
		writeError(w, http.StatusForbidden, "scope_denied", "API 키에 ai:models scope가 없습니다.")
	r.Use(s.securityHeaders)
	r.Use(s.accessLog)
	r.Use(middleware.Compress(5, "application/json", "text/html", "text/css", "application/javascript", "image/svg+xml"))

	// Load balancers and uptime monitors routinely probe with HEAD. chi never
	// derives HEAD from a GET route, so these unauthenticated, side-effect-free
	// probes would otherwise answer 405 on an endpoint that plainly exists.
	getWithHead(r, "/health/live", s.live)
	getWithHead(r, "/health/ready", s.ready)
	getWithHead(r, "/api/v1/health/live", s.live)
	getWithHead(r, "/api/v1/health/ready", s.ready)
	getWithHead(r, "/api/v1/meta", s.meta)
	getWithHead(r, "/api/v1/openapi.json", s.openapi)
	r.Get("/api/v1/auth/options", s.authOptions)
	// RFC 9728: a refused MCP client reads this to find the authorization
	// server, before it has any credential. Both the root document and the
	// per-path one name the same resource.
	getWithHead(r, mcpOAuthMetadataPath, s.protectedResourceMetadata)
	getWithHead(r, mcpOAuthMetadataPath+"/mcp", s.protectedResourceMetadata)
	r.Post("/api/v1/auth/login", s.login)
	r.Get("/api/v1/auth/oidc/start", s.oidcStart)
	r.Get("/api/v1/auth/oidc/callback", s.oidcCallback)
	// Browsers post policy violation reports without credentials, and the
	// tracker runs on the login page, so the report sink and the Momento
	// proxy sit outside the authenticated group.
	r.Post(tracking.ReportPath, s.receiveCSPReport)
	r.Get(tracking.ProxyPath+"/*", s.momentoProxy)
	r.Head(tracking.ProxyPath+"/*", s.momentoProxy)
	r.Post(tracking.ProxyPath+"/*", s.momentoProxy)

	r.Group(func(protected chi.Router) {
		protected.Use(s.authenticate)
		protected.Get("/api/v1/auth/me", s.me)
		protected.With(s.csrf).Post("/api/v1/auth/logout", s.logout)

		protected.Get("/api/v1/dashboard", s.require("dashboard.read", s.dashboard))
		protected.Get("/api/v1/settings", s.require("settings.read", s.listSettings))
		protected.With(s.csrf).Patch("/api/v1/settings", s.require("settings.write", s.updateSettings))
		protected.With(s.csrf).Post("/api/v1/settings/oidc/diagnose", s.require("settings.write", s.diagnoseOIDC))
		protected.Get("/api/v1/settings/legacy/application-managed.yaml", s.exportLegacyManagedYAML)
		protected.Get("/api/v1/tracking/status", s.require("settings.read", s.trackingStatus))
		protected.Get("/api/v1/mcp/oauth/status", s.require("settings.read", s.mcpOAuthStatus))
		protected.With(s.csrf).Delete("/api/v1/tracking/violations", s.require("settings.write", s.forgetTrackingViolations))

		protected.Get("/api/v1/ai/providers", s.require("ai.providers.read", s.listProviders))
		protected.Get("/api/v1/ai/catalog", s.aiCatalog)
		protected.With(s.csrf).Post("/api/v1/ai/providers", s.require("ai.providers.write", s.createProvider))
		protected.Get("/api/v1/ai/providers/{id}", s.require("ai.providers.read", s.getProvider))
		protected.With(s.csrf).Patch("/api/v1/ai/providers/{id}", s.require("ai.providers.write", s.updateProvider))
		protected.With(s.csrf).Delete("/api/v1/ai/providers/{id}", s.require("ai.providers.write", s.deleteProvider))
		protected.With(s.csrf).Post("/api/v1/ai/providers/{id}/test", s.require("ai.providers.write", s.testProvider))

		protected.Get("/api/v1/keys", s.requireAny([]string{"keys.self", "keys.manage"}, s.listKeys))
		protected.With(s.csrf).Post("/api/v1/keys", s.requireAny([]string{"keys.self", "keys.manage"}, s.createKey))
		protected.With(s.csrf).Post("/api/v1/keys/{id}/rotate", s.requireAny([]string{"keys.self", "keys.manage"}, s.rotateKey))
		protected.With(s.csrf).Post("/api/v1/keys/{id}/revoke", s.requireAny([]string{"keys.self", "keys.manage"}, s.revokeKey))
		protected.Get("/api/v1/key-scopes", s.requireAny([]string{"keys.self", "keys.manage"}, s.listKeyScopes))
		protected.With(s.csrf).Patch("/api/v1/key-scopes/{code}", s.require("keys.manage", s.updateKeyScope))

		protected.Get("/api/v1/users", s.require("users.read", s.listUsers))
		protected.With(s.csrf).Patch("/api/v1/users/{id}", s.require("users.write", s.updateUser))
		protected.Get("/api/v1/roles", s.require("users.read", s.listRoles))
		protected.With(s.csrf).Patch("/api/v1/roles/{id}", s.require("roles.manage", s.updateRole))
		protected.Get("/api/v1/permissions", s.require("users.read", s.listPermissions))
		protected.Get("/api/v1/sessions", s.listSessions)
		protected.With(s.csrf).Post("/api/v1/sessions/revoke-others", s.revokeOtherSessions)
		protected.With(s.csrf).Delete("/api/v1/sessions/{id}", s.revokeSession)
		protected.Get("/api/v1/preferences", s.getPreferences)
		protected.With(s.csrf).Patch("/api/v1/preferences", s.updatePreferences)
		protected.With(s.csrf).Patch("/api/v1/profile", s.updateProfile)
		protected.Get("/api/v1/profile/preferences", s.getPreferences)
		protected.With(s.csrf).Patch("/api/v1/profile/preferences", s.updatePreferences)

		protected.Get("/api/v1/workflows", s.requireAny([]string{"workflow.request", "workflow.review", "workflow.manage"}, s.listWorkflows))
		protected.With(s.csrf).Patch("/api/v1/workflows/{code}", s.require("workflow.manage", s.updateWorkflow))
		protected.Get("/api/v1/approvals", s.requireAny([]string{"workflow.request", "workflow.review", "workflow.manage"}, s.listApprovals))
		protected.With(s.csrf).Post("/api/v1/approvals", s.require("workflow.request", s.createApproval))
		protected.With(s.csrf).Post("/api/v1/approvals/{id}/approve", s.require("workflow.review", s.approveRequest))
		protected.With(s.csrf).Post("/api/v1/approvals/{id}/reject", s.require("workflow.review", s.rejectRequest))
		protected.With(s.csrf).Post("/api/v1/approvals/{id}/result", s.require("workflow.request", s.approvalResult))

		protected.Get("/api/v1/legacy/catalog", s.require("schema.read", s.legacyCatalog))
		protected.Get("/api/v1/legacy/tables/{table}/rows", s.require("schema.read", s.legacyRows))
		protected.Get("/api/v1/legacy/tables/{table}/columns", s.require("schema.read", s.legacyColumns))
		protected.Get("/api/v1/audit/events", s.require("audit.read", s.listAuditEvents))
		protected.Get("/api/v1/audit/events/export", s.require("audit.export", s.exportAuditEvents))
		protected.Get("/api/v1/admin/resources/{resource}", s.adminResource)
		protected.With(s.csrf).Post("/api/v1/admin/resources/{resource}", s.mutateAdminResource)
		protected.With(s.csrf).Patch("/api/v1/admin/resources/{resource}/{rowID}", s.mutateAdminResource)
		protected.With(s.csrf).Delete("/api/v1/admin/resources/{resource}/{rowID}", s.mutateAdminResource)

		protected.With(s.aiRequestSecurity).Post("/v1/chat/completions", s.require("ai.use", s.chatCompletions))
		protected.Get("/v1/models", s.models)
	})

	r.With(s.mcpAuthenticate).Post("/mcp", s.mcp)
	r.Get("/mcp", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Allow", "POST")
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "이 MCP 서버는 POST 기반 Streamable HTTP 응답을 사용합니다.")
	})

	r.MethodNotAllowed(s.methodNotAllowed(r))
	r.NotFound(s.spa)
	return r
}

// getWithHead registers one read-only handler for both GET and HEAD. net/http
// discards the body of a HEAD response, so the same handler produces the status
// and headers a probe needs without a separate implementation.
func getWithHead(r chi.Router, pattern string, handler http.HandlerFunc) {
	r.Get(pattern, handler)
  "streamDefault": true,
  "enabled": true,
  "timeoutSeconds": 120
}
```

`contextWindow`과 `maxOutputTokens`의 서버 상한은 각각 262144이고, `baseUrl`은 2000자(문자 수 기준) 이하여야 합니다. 이를 넘으면 400 `provider_invalid`로 거부됩니다. `availableModels`는 최대 200개까지 등록할 수 있고 각 모델 이름은 240자 이하여야 하며, 저장 전에 앞뒤 공백 제거·빈 항목 제거·중복 제거 후 이름순으로 정렬됩니다. `availableModels`를 생략하면 기존 값을 유지하고, 빈 배열을 보내면 목록을 비웁니다. `name`·`defaultModel`은 `varchar` column이고 `availableModels`는 `jsonb` column인데 둘 다 NUL(U+0000)을 담을 수 없으므로, JSON escape `"\u0000"`으로 실제 NUL 바이트가 들어온 값은 생성·수정 모두 저장 전에 400 `provider_invalid`로 거부합니다(여섯 글자 문자열 `\u0000` 자체는 NUL이 아니므로 그대로 저장됩니다).

목록·상세 응답의 `updatedAt`은 수정·삭제 시 필요한 낙관적 잠금 값입니다. PATCH body에 `"expectedUpdatedAt":"<updatedAt>"`을 포함하고 DELETE query에도 같은 RFC3339 값을 전달합니다. 그 사이 다른 요청이 공급자를 변경하면 409 `provider_conflict`가 반환되며, 새 목록을 불러온 뒤 다시 판단해야 합니다. 기본 공급자는 다른 기본 공급자를 먼저 지정하기 전까지 비활성화하거나 삭제할 수 없습니다. 승인 흐름에서도 최종 실행 직전에 같은 버전을 다시 검증합니다.

전역 workflow와 `ai_provider_change` 정책이 모두 활성화되면 생성·수정·삭제는 즉시 적용되지 않고 202와 `pending_approval`, `approvalId`를 반환합니다. 최종 승인 후 서버가 변경을 실행하며 새 API key 원문은 일반 승인 payload에 포함하지 않습니다.

## OpenAI 호환 chat

`GET /v1/models`는 활성 공급자의 기본/가용 model을 OpenAI 목록 형태로 반환합니다. 역할에는 `ai.use` 또는 `ai.providers.read`가 필요하고, API key에는 추가로 `ai:models` scope가 필요합니다. `/api/v1/ai/catalog`도 같은 권한 규칙을 적용하되 개인 플레이그라운드에 필요한 공급자 ID, 모델, context/output 한도와 stream 기본값만 반환합니다.

```bash
curl -N http://localhost:8080/v1/chat/completions \
  -H 'Authorization: Bearer aia_REPLACE_ME' \
  -H 'Content-Type: application/json' \
  -d '{
    "provider_id": "00000000-0000-0000-0000-000000000000",
    "model": "internal-model",
    "messages": [{"role":"user","content":"안녕하세요"}],
    "max_tokens": 1024,
    "stream": true
  }'
```

- chat 본문은 단일 JSON 문서여야 하며 후행 공백(space/tab/CR/LF)만 허용하고, 추가 JSON이나 쓰레기 문자가 붙으면 공급자를 호출하기 전에 400 `invalid_json`으로 거부합니다.
- `provider_id`는 ai-admin 확장 field이며 upstream으로 전달되지 않습니다.
- 생략하면 `ai.default_provider_id`를 사용합니다.
- `model`을 생략하면 공급자 기본 model을 사용합니다.
- `stream`을 생략하면 공급자의 `streamDefault`를 사용합니다.
- `max_tokens`와 `max_completion_tokens`는 정수여야 하고 공급자 한도와 262144를 넘을 수 없습니다.
- stream이면 응답은 `text/event-stream`, `Cache-Control: no-cache, no-transform`, `X-Accel-Buffering: no`로 전달됩니다.
- stream이 아니면 응답은 공급자가 보낸 값과 무관하게 항상 `application/json; charset=utf-8`로 전달됩니다. 공급자가 JSON이 아닌 media type(`application/json`, `application/…+json`, header 없음 외)으로 응답하면 본문을 caller에게 전달하지 않고 502 `ai_response_invalid`로 거부하며, 감사 이벤트 `ai.chat`에 `result=failure`와 `details.reason=invalid_response_content_type`을 남깁니다. stream일 때 `text/event-stream`이 아닌 응답을 502 `ai_stream_invalid`(`details.reason=invalid_stream_content_type`)로 거부하는 것과 같은 계약입니다.
- 200과 header가 나간 뒤 공급자 연결이 답변 도중 끊기거나 공급자 제한 시간을 넘기면, 서버는 응답을 정상적으로 끝내지 않고 중단합니다. client는 본문 읽기 실패(HTTP/1.1은 잘린 chunked stream, HTTP/2는 stream 오류)로 이를 감지해야 하며, 이미 받은 부분 답변을 완결된 답변으로 취급하면 안 됩니다. 중단 사유는 감사 이벤트 `ai.chat`에 `result=failure`와 `details.reason`(`upstream_read_failed`, `upstream_timeout`, `request_cancelled`, `client_write_failed`, `client_flush_failed`)으로 남습니다.

API key에는 `ai:chat` scope와 사용자 역할의 `ai.use` permission이 모두 필요합니다.

## API 키와 scope

| Method | Path | Permission | 설명 |
| --- | --- | --- | --- |
| GET | `/api/v1/keys` | `keys.self` 또는 `keys.manage` | 내 키 조회. `keys.manage` 권한자는 `all=true` 또는 `userId`로 전체/사용자별 조회 가능 |
| POST | `/api/v1/keys` | `keys.self` 또는 `keys.manage` | 키 발급 또는 승인 요청 생성 |
| POST | `/api/v1/keys/{id}/rotate` | `keys.self` 또는 `keys.manage` | 소유 키 회전 또는 승인 요청 생성, 관리자는 타인 키 가능 |
| POST | `/api/v1/keys/{id}/revoke` | `keys.self` 또는 `keys.manage` | 키 폐기 |
| GET | `/api/v1/key-scopes` | `keys.self` 또는 `keys.manage` | scope 정책 목록 |
| PATCH | `/api/v1/key-scopes/{code}` | `keys.manage` | scope 정책 변경 |
