func TestChatRequestJSONContract(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN is not set")
	}

	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	cipher, err := secrets.New(bytes.Repeat([]byte{9}, 32))
	if err != nil {
		t.Fatal(err)
	}
	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
	service := httptest.NewServer(handler)
	defer service.Close()
	session := signIn(t, handler)
	client := service.Client()
	client.Timeout = 10 * time.Second

	// Keep raw bytes intact: session.do marshals its argument as a single JSON value.
	post := func(t *testing.T, path string, body []byte) (int, []byte) {
		t.Helper()
		request, err := http.NewRequest(http.MethodPost, service.URL+path, bytes.NewReader(body))
		if err != nil {
			t.Fatal(err)
		}
		request.Header.Set("Content-Type", "application/json")
		request.Header.Set("X-CSRF-Token", session.csrf)
		for _, cookie := range session.cookies {
			request.AddCookie(cookie)
		}
		response, err := client.Do(request)
		if err != nil {
			t.Fatalf("POST %s: %v", path, err)
		}
		defer response.Body.Close()
		relayed, err := io.ReadAll(response.Body)
		if err != nil {
			t.Fatalf("read response: %v", err)
		}
		return response.StatusCode, relayed
	}
	marshal := func(value any) []byte {
		t.Helper()
		raw, err := json.Marshal(value)
		if err != nil {
			t.Fatal(err)
		}
		return raw
	}

	const answer = `{"id":"chatcmpl-json-contract","choices":[{"message":{"role":"assistant","content":"안녕하세요 {} null xyz"}}]}`
	var mu sync.Mutex
	var calls int
	var lastPayload map[string]any
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var payload map[string]any
		err := json.NewDecoder(r.Body).Decode(&payload)
		mu.Lock()
		calls++
		lastPayload = payload
		mu.Unlock()
		if err != nil {
			t.Errorf("decode upstream request: %v", err)
			http.Error(w, "invalid upstream request", http.StatusBadRequest)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = io.WriteString(w, answer)
	}))
	defer upstream.Close()
	callCount := func() int {
		mu.Lock()
		defer mu.Unlock()
		return calls
	}

	status, created := post(t, "/api/v1/ai/providers", marshal(map[string]any{
		"name": "JSON 요청 공급자", "type": "openai-compatible", "baseUrl": upstream.URL,
		"defaultModel": "test-model", "contextWindow": 131072, "maxOutputTokens": 8192,
	}))
	if status != http.StatusCreated {
		t.Fatalf("provider status=%d body=%s", status, created)
	}
	var providerEnvelope struct {
		Data struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	if err := json.Unmarshal(created, &providerEnvelope); err != nil {
		t.Fatal(err)
	}
	if providerEnvelope.Data.ID == "" {
		t.Fatal("provider creation returned no ID")
	}

	wantMessages := []any{map[string]any{"role": "user", "content": "문자열 안의 {} null xyz는 그대로 보존"}}
	chatBody := func(providerID string) []byte {
		return marshal(map[string]any{
			"provider_id": providerID, "model": "test-model", "stream": false,
			"messages": wantMessages, "seed": 42,
		})
	}
	body := chatBody(providerEnvelope.Data.ID)
	const bodyLimit = 4 << 20
	for _, testCase := range []struct {
		name   string
		suffix string
	}{
		{name: "single_object"},
		{name: "trailing_json_whitespace", suffix: " \t\r\n"},
		{name: "whitespace_at_4_mib_limit", suffix: strings.Repeat(" ", bodyLimit-len(body))},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			before := callCount()
			status, relayed := post(t, "/v1/chat/completions", []byte(string(body)+testCase.suffix))
			if got := callCount() - before; got != 1 {
				t.Errorf("upstream calls=%d want=1", got)
			}
			if status != http.StatusOK {
				t.Fatalf("status=%d want=200 body=%s", status, relayed)
			}
			if string(relayed) != answer {
				t.Errorf("relayed body=%q want=%q", relayed, answer)
			}
			mu.Lock()
			payload := lastPayload
			mu.Unlock()
			if !reflect.DeepEqual(payload["messages"], wantMessages) {
				t.Errorf("upstream messages=%v want=%v", payload["messages"], wantMessages)
			}
			if payload["seed"] != float64(42) || payload["model"] != "test-model" || payload["stream"] != false {
				t.Errorf("upstream seed/model/stream changed: %v", payload)
			}
			if _, supplied := payload["provider_id"]; supplied {
				t.Error("provider_id reached upstream")
			}
		})
	}

	for _, testCase := range []struct {
		name string
		body string
	}{
		{name: "trailing_object", body: string(body) + " {}"},
		{name: "trailing_null", body: string(body) + " null"},
		{name: "trailing_garbage", body: string(body) + " xyz"},
		{name: "whitespace_over_4_mib_limit", body: string(body) + strings.Repeat(" ", bodyLimit-len(body)+1)},
		// A missing provider must not mask the JSON error with provider_unavailable.
		{name: "reject_before_provider_selection", body: string(chatBody("00000000-0000-0000-0000-000000000001")) + " {}"},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			before := callCount()
			status, relayed := post(t, "/v1/chat/completions", []byte(testCase.body))
			if got := callCount() - before; got != 0 {
				t.Errorf("upstream calls=%d want=0", got)
			}
			if status != http.StatusBadRequest {
				t.Errorf("status=%d want=400 body=%s", status, relayed)
			}
			var envelope struct {
				Error struct {
					Code string `json:"code"`
				} `json:"error"`
			}
			if err := json.Unmarshal(relayed, &envelope); err != nil {
				t.Fatalf("decode rejection: %v", err)
			}
			if envelope.Error.Code != "invalid_json" {
				t.Errorf("error code=%q want=invalid_json", envelope.Error.Code)
			}
		})
	}
}

