// methodNotAllowed answers unsupported methods with the same JSON error
// envelope as every other endpoint; chi's default responder writes a bare 405
// with no body, which clients parsing the documented envelope cannot read.
func (s *Server) methodNotAllowed(routes chi.Routes) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		if rctx := chi.RouteContext(r.Context()); rctx != nil && rctx.RoutePath != "" {
			path = rctx.RoutePath
		}
		allowed := make([]string, 0, len(probedMethods))
		for _, method := range probedMethods {
			if routes.Match(chi.NewRouteContext(), method, path) {
				allowed = append(allowed, method)
			}
		}
		writeMethodNotAllowed(w, r, allowed)
	}
}

func writeMethodNotAllowed(w http.ResponseWriter, r *http.Request, allowed []string) {
	if len(allowed) > 0 {
		w.Header().Set("Allow", strings.Join(allowed, ", "))
	}
	writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", fmt.Sprintf("이 경로는 %s 메서드를 지원하지 않습니다.", r.Method))
}

func (s *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		principal, err := s.auth.Authenticate(r)
		if err != nil {
			s.writeAuthFailure(w, r, err, "로그인이 필요하거나 세션이 만료되었습니다.")
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), principalKey{}, principal)))
	})
}

// writeAuthFailure keeps a credential problem apart from a failure to check the
// credential at all. Reporting a database outage as 401 logs every operator out
// of a session that is still valid and tells API key callers their key was
// revoked, so an unverifiable credential answers 503 instead.
func (s *Server) writeAuthFailure(w http.ResponseWriter, r *http.Request, err error, message string) {
	if errors.Is(err, auth.ErrUnauthenticated) {
		writeError(w, http.StatusUnauthorized, "unauthenticated", message)
		return
	}
	s.logger.Warn("authentication backend failure", "error", err, "path", r.URL.Path)
	w.Header().Set("Retry-After", "1")
	writeError(w, http.StatusServiceUnavailable, "auth_unavailable", "인증 정보를 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.")
}

// mcpAuthenticate accepts the two credentials /mcp takes from one
// Authorization: Bearer header: a personal key (aia_…) exactly as before, or —
// only here, never on REST — a Keycloak access token when MCP SSO is on. A
// bearer that is neither gets the same "invalid key" answer it always got.
func (s *Server) mcpAuthenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !validOrigin(r) {
			writeError(w, http.StatusForbidden, "origin_denied", "허용되지 않은 Origin입니다.")
			return
		}
		// The stored SSO settings are read once per refusal or token, not
		// for a key that authenticates.
		var loaded *mcpOAuthConfig
		oauthConfig := func() mcpOAuthConfig {
			if loaded == nil {
				config := s.mcpOAuthConfig(r.Context())
				loaded = &config
			}
			return *loaded
		}
		bearer, hasBearer := bearerCredential(r)
		tokenPresented := hasBearer && !strings.HasPrefix(bearer, "aia_") && looksLikeJWT(bearer)
		var principal auth.Principal
		var err error
		if tokenPresented {
			principal, err = s.mcpOAuthPrincipal(r.Context(), oauthConfig(), bearer)
		} else {
			principal, err = s.auth.Authenticate(r)
		}
		if err != nil {
			if errors.Is(err, auth.ErrUnauthenticated) {
				mcpChallenge(w, oauthConfig(), hasBearer)
			}
			message := "mcp:tools scope가 있는 API 키가 필요합니다."
			var refusal mcpOAuthRefusal
			if errors.As(err, &refusal) {
				// The client gets the sentence; the operator gets the cause —
				// which of signature, issuer, expiry, audience or account it
				// was — under the request id the client can quote back.
				message = refusal.message
				s.logger.Warn("mcp oauth token refused", "error", refusal.detail(), "request_id", middleware.GetReqID(r.Context()), "path", r.URL.Path)
			}
			s.writeAuthFailure(w, r, err, message)
			return
		}
		if principal.ScopeBound() && !principal.HasScope("mcp:tools") {
			mcpChallenge(w, oauthConfig(), hasBearer)
			if principal.AuthMethod == "oauth" {
				writeError(w, http.StatusUnauthorized, "unauthenticated", "관리자 설정 mcp.oauth.scopes 에 mcp:tools 가 없어 SSO 토큰으로는 MCP 를 쓸 수 없습니다.")
				return
			}
			writeError(w, http.StatusUnauthorized, "unauthenticated", "mcp:tools scope가 있는 API 키가 필요합니다.")
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), principalKey{}, principal)))
	})
}

func principalFrom(ctx context.Context) auth.Principal {
	value, _ := ctx.Value(principalKey{}).(auth.Principal)
	return value
}

func (s *Server) require(permission string, handler http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		p := principalFrom(r.Context())
		if !p.HasPermission(permission) {
			s.audit(r, p, "permission.denied", permission, "", "denied", nil)
			writeError(w, http.StatusForbidden, "permission_denied", "이 작업을 수행할 권한이 없습니다.")
			return
		}
		if p.AuthMethod == "api_key" {
			scope := apiScopeForPermission(permission, r.Method)
			if scope != "" && !p.HasScope(scope) {
