func (s *Server) requireAny(permissions []string, handler http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		p := principalFrom(r.Context())
		granted := ""
		for _, permission := range permissions {
			if p.HasPermission(permission) {
				granted = permission
				break
			}
		}
		if granted == "" {
			s.audit(r, p, "permission.denied", strings.Join(permissions, "|"), "", "denied", nil)
