func (s *Server) audit(r *http.Request, p auth.Principal, action, resourceType, resourceID, result string, details any) {
	if details == nil {
		details = map[string]any{}
	}
	detailJSON, _ := json.Marshal(details)
	var actor any
	if p.ID != uuid.Nil {
		actor = p.ID
	}
	var ip any
	if parsed := strings.TrimSpace(clientIP(r)); parsed != "" {
		ip = parsed
	}
	auditContext, cancel := context.WithTimeout(context.WithoutCancel(r.Context()), 3*time.Second)
	defer cancel()
	_, err := s.db.Pool.Exec(auditContext, `INSERT INTO ai_admin.audit_event(actor_user_id,actor_type,action,resource_type,resource_id,result,ip_address,request_id,details)
VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb)`, actor, authMethod(p), action, nullString(resourceType), nullString(storableResourceID(resourceID)), result, ip, middleware.GetReqID(r.Context()), detailJSON)
	if err != nil {
		s.logger.Warn("write audit event", "error", err, "action", action)
