func boundedRequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if storableRequestID(middleware.GetReqID(r.Context())) {
			next.ServeHTTP(w, r)
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), middleware.RequestIDKey, newRequestID())))
	})
}

// storableRequestID reports whether the identifier fits the audit column and
// carries only characters that stay readable in a log line or an audit export.
func storableRequestID(value string) bool {
	if value == "" || utf8.RuneCountInString(value) > requestIDMaximum {
		return false
	}
	return safeReferenceRunes(value)
}

func safeReferenceRunes(value string) bool {
	for _, character := range value {
		if (character >= 'a' && character <= 'z') || (character >= 'A' && character <= 'Z') ||
			(character >= '0' && character <= '9') || strings.ContainsRune("-._:/", character) {
			continue
		}
		return false
	}
	return true
}

func newRequestID() string {
	buffer := make([]byte, 16)
	if _, err := rand.Read(buffer); err != nil {
		return "unidentified"
	}
	return "req-" + hex.EncodeToString(buffer)
}

