func (s *Server) recoverer(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			recovered := recover()
			if recovered == nil {
				return
			}
			// A handler that deliberately abandons a partly written response
			// signals it with http.ErrAbortHandler; swallowing that here would
			// leave the caller holding a truncated body under a 200 status.
			if recovered == http.ErrAbortHandler {
				panic(recovered)
			}
			s.logger.Error("panic recovered", "error", recovered, "stack", string(debug.Stack()), "request_id", middleware.GetReqID(r.Context()))
			writeError(w, http.StatusInternalServerError, "internal_error", "요청 처리 중 오류가 발생했습니다.")
		}()
		next.ServeHTTP(w, r)
	})
